using System.IO;
namespace MRS;
internal static class Update038Tests
{
 internal static void Run(Action<bool,string> check)
 {
  var now=DateTimeOffset.UtcNow;var profile=new TrunkProfile("p","Site 22","P25",851012500,[]);var m=new TrunkFollower();m.Start(profile,now);
  var ch=new P25Channel(0x1002,1,2,851025000,806025000,null,1,"received IDEN");
  PacketObservation Grant(int tg=91)=>new(now,"test",false,profile.ControlHz,null,"TSBK CRC valid","","","","Grant","",null,"","P25 Phase I",true,P25Identity:new(0x293,0xBEE00,0x348,1,22),P25Assignments:[new(tg,12345,0,ch)]);
  m.ObserveP25(Grant() with{Validated=false},now);check(m.Active==null,"Following rejects failed control CRC");
  m.ObserveP25(Grant() with{Validation="NID BCH valid"},now);check(m.Active==null,"Header-only P25 cannot authorize a call");
  m.ObserveP25(Grant() with{FrequencyHz=852000000},now);check(m.Active==null,"P25 grants must originate on selected control frequency");
  m.ObserveP25(Grant() with{P25Assignments=[new(91,1,0,ch with{DownlinkHz=null})]},now);check(m.Active==null&&m.Events.Any(e=>e.Kind=="Unresolved"),"Missing identifier table stays unresolved");
  m.ObserveP25(Grant() with{P25Assignments=[new(91,1,0,ch with{SlotsPerCarrier=2})]},now);check(m.Active==null,"Phase II grants are not sent to Phase I voice");
  m.ObserveP25(Grant() with{P25Assignments=[new(91,1,64,ch)]},now);check(m.Active==null,"Encrypted grant does not authorize following");
  m.Allowed=[92];m.ObserveP25(Grant(),now);check(m.Active==null,"Allow list excludes other talkgroups");m.Allowed.Clear();m.Ignored=[91];m.ObserveP25(Grant(),now);check(m.Active==null,"Ignore list excludes selected talkgroup");m.Ignored.Clear();m.Hold=92;m.ObserveP25(Grant(),now);check(m.Active==null,"Hold excludes different talkgroup");m.Hold=null;
  m.ObserveP25(Grant(),now);check(m.Active is{Hz:851025000,Talkgroup:91,Radio:12345,Nac:0x293},"CRC-valid resolved Phase I grant selects expected frequency/group/NAC");
  m.ObserveP25(Grant(92),now.AddSeconds(1));check(m.Active?.Talkgroup==91,"A new group does not preempt active call");
  m.Voice(now.AddSeconds(2));m.Tick(now.AddSeconds(4));check(m.Active!=null,"Received voice extends hang time");m.Tick(now.AddSeconds(5));check(m.Active==null,"Quiet hang returns to control");
  m.ObserveP25(Grant(),now);m.Skip(now);m.ObserveP25(Grant(),now.AddSeconds(1));check(m.Active==null,"Skip suppresses immediate regrant for five seconds");m.ObserveP25(Grant(),now.AddSeconds(6));check(m.Active!=null,"Skipped group becomes eligible after timeout");
  m.MaximumSeconds=5;m.Voice(now.AddSeconds(12));m.Tick(now.AddSeconds(12));check(m.Active==null,"Maximum call timer cannot be extended indefinitely by audio");
  m.Start(profile,now);m.ObserveP25(Grant(),now);m.ObserveP25(Grant() with{P25Identity=new(0x294,0xBEE00,0x348,1,23),P25Assignments=[]},now);check(m.Active==null,"Serving NAC/site change discards old call");
  var capProfile=new TrunkProfile("cap","User researched system","Capacity Plus",461150000,[new(1,461150000,true),new(2,461175000,false)]);m.Start(capProfile,now);
  var status=new CapStatus(1,[new(3,91)]);m.ObserveCap(status,461150000,now);m.ObserveCap(status,461150000,now);check(m.Active==null,"Unconfirmed DMR carrier map cannot authorize following");
  capProfile=capProfile with{Carriers=[new(1,461150000,true),new(2,461175000,true)]};m.Start(capProfile,now);m.ObserveCap(status,461150000,now);check(m.Active==null,"Capacity Plus needs repeated matching group status");m.ObserveCap(status,461150000,now.AddMilliseconds(100));check(m.Active is{Hz:461175000,Slot:1,Talkgroup:91},"LSN 3 maps to carrier LCN 2 slot 1");m.End(now,"test");m.ObserveCap(new(1,[new(4,92)]),461150000,now);m.ObserveCap(new(1,[new(4,92)]),461150000,now);check(m.Active is{Slot:2,Talkgroup:92},"LSN 4 maps to carrier LCN 2 slot 2");
  var rest=DmrBits.Parse(DmrTests.Bits(Convert.FromHexString(TrunkTests.CapCall)),null)!;m.Start(capProfile,now);m.ObserveDmr(rest,461150000,now);m.ObserveDmr(rest,461150000,now);check(m.ControlHz==461150000,"Rest hopping waits for three observations");m.ObserveDmr(rest,461150000,now);check(m.ControlHz==461175000,"Repeated rest LSN uses confirmed map");
  m.ObserveDmr(rest with{ColorCode=rest.ColorCode+1},461175000,now);check(!m.Running,"Color code change stops selected profile rather than merging systems");
  bool rejected=false;try{TrunkFollower.Validate(capProfile with{Carriers=[new(1,1),new(1,2)]});}catch(IOException){rejected=true;}check(rejected,"Duplicate carrier LCNs are rejected");
  var wire=DmrBits.Parse(DmrTests.Bits(Convert.FromHexString(TrunkTests.CapStatus)),null)! with{Slot=1};var parser=new CapStatusDecoder();check(parser.Feed(wire,now) is{Rest:1},"Independent MMDVM CSBK passes payload CRC and bounded Cap+ parser");
  byte[] Payload(byte flag,byte[] data){var b=new byte[12];b[0]=0xBE;b[1]=0x10;b[2]=(byte)(flag<<6|1);Array.Copy(data,0,b,3,Math.Min(7,data.Length));int crc=TrunkSignaling.Crc16(b.AsSpan(0,10))^0xA5A5;b[10]=(byte)(crc>>8);b[11]=(byte)crc;return b;}
  DmrObservation Wire(byte[] b)=>wire with{Payload=Convert.ToHexString(b),Slot=1,DataType=3,LinkValid=true};
  var single=Payload(3,[0x80,91,0x80,92]);check(parser.Feed(Wire(single),now)?.Groups.SequenceEqual(new[]{new CapGroup(1,91),new CapGroup(9,92)})==true,"Both Cap+ activity banks retain LSN and talkgroup");
  for(int bit=0;bit<96;bit++){var b=(byte[])single.Clone();b[bit/8]^=(byte)(128>>(bit%8));check(new CapStatusDecoder().Feed(Wire(b),now)==null,$"Cap+ follower rejects CSBK corruption bit {bit}");}
  parser=new();check(parser.Feed(Wire(Payload(2,[0xFF,1,2,3,4,5,6])),now)==null,"First fragment cannot publish partial Cap+ groups");check(parser.Feed(Wire(Payload(1,[7,8,0,0,0,0,0])),now.AddMilliseconds(100))?.Groups.Length==8,"Fragmented Cap+ status assembles bounded group list");
  parser=new();parser.Feed(Wire(Payload(2,[0xFF,1,2,3,4,5,6])),now);check(parser.Feed(Wire(Payload(1,[7,8,0,0,0,0,0])),now.AddSeconds(2))==null,"Stale continuation is discarded");check(CapStatusDecoder.Parse([0,0,0,255,1],1)==null,"Truncated TG list cannot invent missing groups");
  using var good=new P25VoiceDecoder();var audio=new List<byte>();good.Audio+=audio.AddRange;var all=VoiceFixtures.Hdu.Concat(VoiceFixtures.Ldu1).Concat(VoiceFixtures.Ldu2).ToArray();var framer=new P25C4fm();var units=new List<P25VoiceUnit>();framer.VoiceUnit+=units.Add;framer.Process(P25Tests.Signal(symbols:all));var header=units.First(u=>u.Duid==0&&u.Payload.Length>0);var meta=ImbeVocoder.ReadMetadata(0,header.Payload)!;int tg=meta[13]<<8|meta[14];
  good.ExpectedNac=header.Nac;good.ExpectedGroup=tg;foreach(var u in units)good.Accept(u);check(audio.Count>0,"Independent OP25 voice passes matching grant NAC/group gate");
  using var wrongNac=new P25VoiceDecoder{ExpectedNac=header.Nac^1,ExpectedGroup=tg};int hits=0;wrongNac.Audio+=_=>hits++;foreach(var u in units)wrongNac.Accept(u);check(hits==0,"Wrong NAC never reaches followed audio");
  using var wrongGroup=new P25VoiceDecoder{ExpectedNac=header.Nac,ExpectedGroup=tg^1};wrongGroup.Audio+=_=>hits++;foreach(var u in units)wrongGroup.Accept(u);check(hits==0,"Wrong group never reaches followed audio");
  var pipeline=new P25Pipeline{Enabled=true};var ctx=new PacketContext("stable","fixture",false,851012500);pipeline.Feed(P25Tests.Signal(symbols:P25ChannelFixtures.Symbols),ctx);pipeline.Drain();pipeline.Reacquire();pipeline.Feed(P25Tests.Signal(symbols:P25Tests.Symbols),ctx);check(pipeline.Drain().Any(p=>p.P25Assignments?.Any(a=>a.Channel.DownlinkHz==851025000)==true),"Intentional capture reacquisition retains received P25 identifier table");
  m=new TrunkFollower{RequireConfirmations=false};m.Start(new("loose","Research","Capacity Plus",461150000,[new(1,461150000,false),new(2,461175000,false)]),now);m.ObserveCap(new(1,[new(3,91)]),461150000,now);check(m.Active is{Hz:461175000,Talkgroup:91}&&m.Active.Evidence.Contains("TENTATIVE"),"Optional confirmation permits a single status with an entered unconfirmed map");m.End(now,"test");m.ObserveDmr(rest,461150000,now);check(m.ControlHz==461175000,"Optional confirmation permits candidate rest mapping after one observation");
  m=new TrunkFollower{RequireConfirmations=false};m.Start(profile,now);m.ObserveP25(Grant() with{Validated=false},now);check(m.Active==null,"Optional evidence confirmation does not turn failed CRC into an actionable P25 grant");
  check(!DiscoveryVisibility.Show(0,1)&&DiscoveryVisibility.Show(1,1)&&DiscoveryVisibility.Show(2,0),"Discovery modes expose tentative and rejected evidence only when selected");check(DiscoveryVisibility.Unverified(wire with{LinkValid=false})&&DiscoveryVisibility.Unverified(wire with{SlotCorrections=3}),"CRC-failed and heavily corrected candidates remain labeled unverified");
  var legacy=System.Text.Json.JsonSerializer.Deserialize<TrunkSaved>("{\"Profile\":{\"Id\":\"old\",\"Name\":\"Existing\",\"Protocol\":\"P25\",\"ControlHz\":851012500,\"Carriers\":[]}}");check(legacy?.RequireConfirmations==true,"Existing saved profiles keep confirmation enabled by default");var loose=new TrunkSaved(profile,RequireConfirmations:false);check(System.Text.Json.JsonSerializer.Deserialize<TrunkSaved>(System.Text.Json.JsonSerializer.Serialize(loose))?.RequireConfirmations==false,"Optional confirmation persists per profile");
  using(var radio=new TrunkRadio()){radio.Start(profile);var iq=P25Tests.Iq(repeats:3,symbols:P25ChannelFixtures.Symbols);for(int offset=0;offset<iq.Length;offset+=32768){radio.Feed(new(offset,profile.ControlHz,240000,iq.Skip(offset).Take(Math.Min(32768,iq.Length-offset)).ToArray(),200000));Thread.Sleep(10);}bool selected=SpinWait.SpinUntil(()=>{lock(radio.Sync)return radio.Model.Active!=null;},5000);lock(radio.Sync)check(selected&&radio.Model.Active is{Hz:851025000,Talkgroup:4660}&&radio.Dropped==0,"Real I/Q worker decodes received IDEN/grant and selects in-span P25 voice");radio.Stop();check(!radio.Running&&radio.DrainAudio().Length==0,"Stop discards queued followed audio");}

 }
}

